From 4382aebd74c690e171cec77a7c67f02dccd2a83e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:28:32 +0100
Subject: [PATCH] klipper: add an About page to the Clipboard settings

The Clipboard settings use their own dialog instead of the standard
widget one, so they never got the About page every other widget has. Add
one built from the applet's metadata, with version, website and authors.

BUG: 523828
---
 klipper/configdialog.cpp | 50 ++++++++++++++++++++++++++++++++++++++++
 klipper/configdialog.h   |  9 ++++++++
 2 files changed, 59 insertions(+)

diff --git a/klipper/configdialog.cpp b/klipper/configdialog.cpp
index 592dfd8dd8..7d74b7f6b6 100644
--- a/klipper/configdialog.cpp
+++ b/klipper/configdialog.cpp
@@ -21,11 +21,14 @@
 #include <QVBoxLayout>
 #include <QWindow>

+#include <KAboutData>
 #include <KActionCollection>
 #include <KConfigSkeleton>
 #include <KLocalization>
 #include <KMessageWidget>
+#include <KPluginMetaData>
 #include <KShortcutsEditor>
+#include <KTitleWidget>
 #include <kconfigskeleton.h>
 #include <kglobalaccel.h>
 #include <kmessagebox.h>
@@ -515,6 +518,52 @@ void ActionsWidget::onItemChanged(QTreeWidgetItem *item, int /*col*/)
     }
 }

+AboutWidget::AboutWidget(QWidget *parent)
+    : QWidget(parent)
+{
+    const KPluginMetaData metaData = KPluginMetaData::findPluginById(u"plasma/applets"_s, u"org.kde.plasma.clipboard"_s);
+
+    auto *layout = new QVBoxLayout(this);
+
+    auto *title = new KTitleWidget(this);
+    title->setText(metaData.name());
+    title->setComment(metaData.description());
+    title->setIcon(QIcon::fromTheme(metaData.iconName()), KTitleWidget::ImageLeft);
+    title->setIconSize(QSize(48, 48));
+    layout->addWidget(title);
+
+    auto *form = new QFormLayout;
+    form->addRow(i18nc("@label", "Version:"), new QLabel(QStringLiteral(KLIPPER_VERSION_STRING), this));
+
+    const auto createLinkLabel = [this](const QString &url, const QString &text) {
+        auto *label = new QLabel(u"<a href=\"%1\">%2</a>"_s.arg(url, text.toHtmlEscaped()), this);
+        label->setTextInteractionFlags(Qt::TextBrowserInteraction);
+        label->setOpenExternalLinks(true);
+        return label;
+    };
+
+    if (!metaData.website().isEmpty()) {
+        form->addRow(i18nc("@label", "Website:"), createLinkLabel(metaData.website(), metaData.website()));
+    }
+    if (!metaData.bugReportUrl().isEmpty()) {
+        form->addRow(i18nc("@label", "Get help:"), createLinkLabel(metaData.bugReportUrl(), i18nc("@action:button urlbutton", "Report an issue")));
+    }
+
+    const KAboutLicense license = KAboutLicense::byKeyword(metaData.license());
+    form->addRow(i18nc("@label", "License:"), new QLabel(license.name(KAboutLicense::FullName), this));
+
+    const QList<KAboutPerson> authors = metaData.authors();
+    for (int i = 0; i < authors.size(); ++i) {
+        const KAboutPerson &author = authors.at(i);
+        QWidget *authorLabel =
+            author.emailAddress().isEmpty() ? new QLabel(author.name(), this) : createLinkLabel(u"mailto:"_s + author.emailAddress(), author.name());
+        form->addRow(i == 0 ? i18ncp("@label", "Author:", "Authors:", authors.size()) : QString(), authorLabel);
+    }
+
+    layout->addLayout(form);
+    layout->addStretch();
+}
+
 //////////////////////////
 //  ConfigDialog        //
 //////////////////////////
@@ -536,6 +585,7 @@ ConfigDialog::ConfigDialog(QWidget *parent, KConfigSkeleton *skeleton, Klipper *
     shortcutsLayout->addWidget(m_shortcutsWidget);

     addPage(shortcutsPage, i18nc("Shortcuts Config", "Shortcuts"), QStringLiteral("preferences-desktop-keyboard"), i18n("Shortcuts Configuration"));
+    addPage(new AboutWidget(this), i18nc("@title:tab", "About"), QStringLiteral("help-about"), QString(), false);

     connect(m_actionsPage, &ActionsWidget::widgetChanged, this, &ConfigDialog::settingsChangedSlot);
     connect(m_actionsPage, &ActionsWidget::widgetChanged, this, &ConfigDialog::updateActionsOffered);
diff --git a/klipper/configdialog.h b/klipper/configdialog.h
index d3d44c97fb..c8e0e5000b 100644
--- a/klipper/configdialog.h
+++ b/klipper/configdialog.h
@@ -40,6 +40,15 @@ private:
     QSpinBox *m_historySizeSb;
 };

+class AboutWidget : public QWidget
+{
+    Q_OBJECT
+
+public:
+    explicit AboutWidget(QWidget *parent);
+    ~AboutWidget() override = default;
+};
+
 class PopupWidget : public QWidget
 {
     Q_OBJECT
